-- Corrige permissão inexistente "financeiro" usada na participação no fundo da IES.
-- Passa a exigir a permissão existente "bancarios" (titular continua com acesso total). Alteração aditiva, sem perda de dados.
CREATE OR REPLACE FUNCTION public.author_metrics(_month date DEFAULT date_trunc('month',now())::date) RETURNS TABLE(fund_type text,owner_id uuid,course_id uuid,title text,eligible_minutes numeric,approved_minutes numeric,completion numeric,audience numeric,production numeric,score numeric,estimated_cents bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _month IS NULL OR date_trunc('month',_month)::date<>_month THEN RAISE EXCEPTION 'Mês inválido'; END IF; RETURN QUERY SELECT c.* FROM public.calculate_author_fund(_month) c WHERE (c.fund_type='professor' AND c.owner_id=auth.uid() AND public.current_profile_role()='professor') OR (c.fund_type='ies' AND public.organization_permission(c.owner_id,'ies','bancarios')) OR (public.is_admin() AND public.current_profile_role() NOT IN('professor','ies','empresa','colaborador')); END $$;
ALTER POLICY author_scores_financial_guard ON public.author_scores USING((fund_type='professor' AND owner_id=auth.uid() AND public.current_profile_role()='professor') OR (fund_type='ies' AND public.organization_permission(owner_id,'ies','bancarios')) OR (public.is_admin() AND public.current_profile_role() NOT IN('professor','ies','empresa','colaborador')));
